/*
 * generrh.c - C23 replacement for generrh.pl
 *
 * Reads errors.def and build.txt from the current directory and generates:
 *
 *   errcodes.c          C error code definitions (errcodes.h is extracted
 *                       from this file by the headerer tool)
 *   include/error.bas   BASIC error constants
 *
 * Faithful port: the generated files are byte identical to the ones the
 * Perl script creates. Note that the stray '\r' that the Perl chomp()
 * leaves on the build number is intentionally preserved.
 */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LANGUAGES 16
#define MAX_MESSAGES  4096

struct language {
    char  name[4];
    char *messages[MAX_MESSAGES];
};

static struct language languages[MAX_LANGUAGES];
static int           n_languages = 0;
static int           current_error_code = 2;
static int           last_error_code = 0;
static int           error_type = 0;        /* 0 = %CT compile time, 1 = %RT run time */
static const char   *module = "?";

static FILE *out;
static FILE *bas;

static int is_word(char c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '_';
}

static int is_sp(char c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
}

static struct language *language(const char *name)
{
    for (int i = 0; i < n_languages; i++)
        if (strcmp(languages[i].name, name) == 0) return &languages[i];
    if (n_languages >= MAX_LANGUAGES) {
        fprintf(stderr, "generrh: too many languages\n");
        exit(1);
    }
    struct language *l = &languages[n_languages++];
    snprintf(l->name, sizeof l->name, "%s", name);
    return l;
}

/* Perl: /%RT\s*$/ and /%CT\s*$/ - the line, with trailing spaces ignored, ends with the marker */
static int ends_with_marker(const char *line, const char *marker)
{
    size_t len = strlen(line);
    while (len > 0 && is_sp(line[len - 1])) len--;
    size_t mlen = strlen(marker);
    return len >= mlen && memcmp(line + len - mlen, marker, mlen) == 0;
}

/* Perl: m{(\w\w)/(.*)} - leftmost two word chars followed by '/'; message is the rest */
static int find_lang_split(const char *line, size_t *lang_at, size_t *msg_at)
{
    for (size_t i = 0; line[i]; i++) {
        if (line[i + 1] == 0 || line[i + 2] == 0) break;
        if (is_word(line[i]) && is_word(line[i + 1]) && line[i + 2] == '/') {
            *lang_at = i;
            *msg_at = i + 3;
            return 1;
        }
    }
    return 0;
}

/* Perl: ^(.+)\s+(.+)$ with a greedy first group - split at the last run of spaces */
static int split_tail(const char *line, char **head_end, const char **tail)
{
    size_t len = strlen(line);
    size_t i = len;
    while (i > 0 && is_sp(line[i - 1])) i--;        /* end of the last token  */
    if (i == 0) return 0;
    size_t j = i;
    while (j > 0 && !is_sp(line[j - 1])) j--;       /* start of the last token */
    if (j == 0) return 0;                           /* no space before it     */
    size_t k = j;
    while (k > 0 && is_sp(line[k - 1])) k--;        /* end of the head        */
    if (k == 0) return 0;                           /* head would be empty    */
    *head_end = (char *)line + k;
    *tail = line + j;
    return 1;
}

/* Perl run time error symbol to BASIC constant: ucfirst then remove '_', upping the next letter */
static void bas_symbol(char *symbol)
{
    size_t n = strlen(symbol);
    for (size_t i = 0; i + 1 < n; i++)
        if (symbol[i] == '_' && symbol[i + 1] >= 'a' && symbol[i + 1] <= 'z')
            symbol[i + 1] = (char)(symbol[i + 1] - 'a' + 'A');
    if (n && symbol[0] >= 'a' && symbol[0] <= 'z')
        symbol[0] = (char)(symbol[0] - 'a' + 'A');
    size_t w = 0;
    for (size_t i = 0; i < n; i++)
        if (symbol[i] != '_') symbol[w++] = symbol[i];
    symbol[w] = 0;
}

int main(void)
{
    char build[256] = "";

    FILE *q = fopen("build.txt", "r");
    if (!q) { fprintf(stderr, "Can not open the build file.\n"); return 1; }
    if (!fgets(build, sizeof build, q)) build[0] = 0;
    fclose(q);
    {   /* chomp: remove the trailing '\n' only, keep a possible '\r' */
        size_t l = strlen(build);
        if (l && build[l - 1] == '\n') build[--l] = 0;
    }

    FILE *in = fopen("errors.def", "r");
    if (!in) { fprintf(stderr, "Can not open errors.def\n"); return 1; }

    out = fopen("errcodes.c", "w");
    if (!out) { fprintf(stderr, "Can not output errcodes.c\n"); return 1; }

    bas = fopen("include/error.bas", "w");
    if (!bas) { fprintf(stderr, "Can nor output include/error.bas\n"); return 1; }

    fprintf(bas,
        "' This file was automatically generated by the program generrh\n"
        "' using the error code definition file errors.def from the\n"
        "' ScriptBasic distribution\n"
        "'\n"
        "' This file is part of the ScriptBasic distribution and is\n"
        "' specific to the actual build it was shipped. Do not use\n"
        "' this file for any version or build of the ScriptBasic\n"
        "' interpreter other than the one this file was shipped.\n"
        "'\n"
        "' THIS FILE IS FOR V1.0 BUILD %s\n"
        "'\n"
        "Global Const sbErrorOK = 0\n"
        "Global Const sbErrorMemory = 1\n\n", build);

    fputs("/* \n"
          "FILE: errcodes.c\n"
          "HEADER: errcodes.h\n"
          "\n"
          "This file was automatically generated by generrh from the file errors.def\n"
          "Do not edit this file. Modify errors.def and run bin/tools/generrh to regenerate this file.\n"
          "\n"
          "TO_HEADER:\n"
          "\n", out);

    char  *line = NULL;
    size_t capacity = 0;
    ssize_t len;

    while ((len = getline(&line, &capacity, in)) > 0) {
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = 0;

        {   /* skip empty lines and comments */
            char *s = line;
            while (is_sp(*s)) s++;
            if (*s == 0 || *s == '#') continue;
        }

        if (ends_with_marker(line, "%RT")) { error_type = 1; continue; }
        if (ends_with_marker(line, "%CT")) { error_type = 0; continue; }

        char *mod = strstr(line, "%MODULE");
        if (mod) {
            char *name = mod + strlen("%MODULE");
            while (is_sp(*name)) name++;
            size_t n = strlen(name);
            while (n > 0 && is_sp(name[n - 1])) name[--n] = 0;
            module = strdup(name);
            fprintf(out, "#define %s_ERROR_SUCCESS 0\n", module);
            fprintf(out, "#define %s_ERROR_MEMORY_LOW 1\n", module);
            language("en")->messages[1] = strdup("Not enough memory");
            continue;
        }

        size_t lang_at, msg_at;
        if (find_lang_split(line, &lang_at, &msg_at)) {
            char lang[3] = { line[lang_at], line[lang_at + 1], 0 };
            const char *message = line + msg_at;
            struct language *l = language(lang);
            if (last_error_code >= 0 && last_error_code < MAX_MESSAGES)
                l->messages[last_error_code] = strdup(message);
            if (strcmp(lang, "en") == 0 && error_type) {
                fprintf(bas, "' %s\n' ", message);
                for (size_t i = 0; i < strlen(message); i++) fputc('-', bas);
                fputs("\n\n", bas);
            }
            continue;
        }

        char *head_end = NULL;
        const char *tail = NULL;
        int has_tail = split_tail(line, &head_end, &tail);
        char symbol[1024];
        if (has_tail) {
            size_t hl = (size_t)(head_end - line);
            if (hl >= sizeof symbol) hl = sizeof symbol - 1;
            memcpy(symbol, line, hl);
            symbol[hl] = 0;
        } else {
            snprintf(symbol, sizeof symbol, "%s", line);
        }

        if (error_type) {
            char basic[1024];
            if (has_tail) {
                snprintf(basic, sizeof basic, "%s", tail);
            } else {
                size_t i;
                for (i = 0; symbol[i] && i < sizeof basic - 1; i++) {
                    char c = symbol[i];
                    basic[i] = (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
                }
                basic[i] = 0;
            }
            bas_symbol(basic);
            fprintf(bas, "Global Const sbError%s = %d\n", basic, current_error_code);
        }

        fprintf(out, "#define %s_ERROR_%s %d\n", module, symbol, current_error_code);
        last_error_code = current_error_code++;
    }
    fclose(in);

    fprintf(out, "#define MAX_ERROR_CODE %d\n", current_error_code);
    fputs("typedef struct { char *language; char **array; } tErrorMessageArray;\n"
          "extern tErrorMessageArray ErrorMessageArray[];\n", out);
    for (int i = 0; i < n_languages; i++)
        fprintf(out, "extern char  *%s_error_messages[];\n", languages[i].name);

    fputs("*/\n"
          "#include <stdio.h>\n"
          "#include \"errcodes.h\"\n", out);

    for (int i = 0; i < n_languages; i++) {
        struct language *l = &languages[i];
        l->messages[0] = strdup("SUCCESS");
        fprintf(out, "char *%s_error_messages[] ={\n", l->name);
        for (int n = 0; n < current_error_code; n++)
            fprintf(out, "\"%s\",\n", l->messages[n] ? l->messages[n] : "");
        fputs("NULL\n};\n", out);
    }

    fputs("tErrorMessageArray ErrorMessageArray[]={\n", out);
    for (int i = 0; i < n_languages; i++)
        fprintf(out, "\"%s\",%s_error_messages,\n", languages[i].name, languages[i].name);
    fputs("NULL,NULL\n};\n", out);

    fclose(out);
    fclose(bas);
    return 0;
}
